import tempfile, os
from flaskr.db import init_db

raised = False
try:
    init_db()
except RuntimeError:
    raised = True

assert raised is True

def test_init_db_negative_no_app_context():
    raised2 = False
    try:
        init_db()
    except RuntimeError:
        raised2 = True
    assert raised2 is True
